'use client';

import React, { useState, useEffect } from 'react';
import { QRCodeSVG } from 'qrcode.react';
import axios from 'axios';
import { supabase } from '@/lib/supabase';
import { CheckCircle2, Loader2, AlertCircle, ShieldCheck, ArrowRight, Lock, CreditCard, Copy, Clock, ArrowLeft, Check } from 'lucide-react';
import { useParams } from 'next/navigation';

interface PaymentState {
    step: 'details' | 'payment' | 'verifying' | 'success' | 'failed' | 'expired' | 'manual_upload' | 'verified';
    amount: string;
    name: string;
    email: string;
    utr: string;
    error: string;
    screenshot_url?: string;
}

const PaymentPage: React.FC = () => {
    const params = useParams();
    const urlSessionId = params?.orderId as string; // This is the UUID from URL (Session ID)

    const [state, setState] = useState<PaymentState>({
        step: 'details',
        amount: '',
        name: '',
        email: '',
        utr: '',
        error: '',
    });

    const [sessionId, setSessionId] = useState<string>(urlSessionId || '');
    const [officialOrderId, setOfficialOrderId] = useState<string>(''); // This will be the SF-2025-X ID
    const [copied, setCopied] = useState(false);
    const [timeLeft, setTimeLeft] = useState(15 * 60); // 15 minutes in seconds


    const UPI_ID = '9515358045@ybl';
    const MERCHANT_NAME = 'Shark Funded';

    useEffect(() => {
        if (urlSessionId) {
            setSessionId(urlSessionId);
        }
    }, [urlSessionId]);

    useEffect(() => {
        let timer: ReturnType<typeof setInterval>;
        if (state.step === 'payment' && timeLeft > 0) {
            timer = setInterval(() => {
                setTimeLeft((prev) => prev - 1);
            }, 1000);
        } else if (timeLeft === 0 && state.step === 'payment') {
            setState(prev => ({ ...prev, step: 'expired' }));
        }
        return () => clearInterval(timer);
    }, [state.step, timeLeft]);

    const formatTime = (seconds: number) => {
        const mins = Math.floor(seconds / 60);
        const secs = seconds % 60;
        return `${mins}:${secs.toString().padStart(2, '0')}`;
    };

    const handleDetailsSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        if (!state.amount || !state.name || !state.email) {
            setState(prev => ({ ...prev, error: 'Please fill in all fields' }));
            return;
        }

        setTimeLeft(15 * 60); // Reset timer
        setState(prev => ({ ...prev, step: 'payment', error: '' }));
    };

    const handleVerify = async () => {
        if (!state.utr) {
            setState(prev => ({ ...prev, error: 'Please enter UTR number' }));
            return;
        }

        setState(prev => ({ ...prev, step: 'verifying', error: '' }));

        // 1. Check if UTR is already used
        try {
            const { data: existingTxn, error: checkError } = await supabase
                .from('transactions')
                .select('*')
                .eq('utr', state.utr)
                .eq('status', 'verified')
                .single();

            if (checkError && checkError.code !== 'PGRST116') { // PGRST116 is "Row not found"
                console.error('Error checking UTR:', checkError);
                setState(prev => ({ ...prev, step: 'failed', error: 'Error checking transaction status' }));
                return;
            }

            if (existingTxn) {
                setState(prev => ({ ...prev, step: 'failed', error: 'This UTR has already been used for a verified payment.' }));
                return;
            }
        } catch (err) {
            console.error('Unexpected error checking UTR:', err);
        }

        // Polling logic: Check every 5 seconds for up to 2 minutes (24 attempts)
        let attempts = 0;
        const maxAttempts = 24;
        const pollInterval = 5000; // 5 seconds

        const checkPayment = async () => {
            try {
                attempts++;
                console.log(`Verification attempt ${attempts}/${maxAttempts}`);

                const response = await axios.post('/api/verify-payment', {
                    utr: state.utr,
                    amount: state.amount,
                    orderId: sessionId, // Pass Session ID to backend for tracking
                });

                if (response.data.success) {
                    // Success! Record in Supabase
                    // The DB Trigger will automatically generate the 'order_id' (SF-2025-X) because status is verified

                    const { data: insertedData, error: dbError } = await supabase
                        .from('transactions')
                        .insert([
                            {
                                amount: state.amount,
                                utr: state.utr,
                                session_id: sessionId, // Store UUID in session_id
                                status: 'verified',
                                customer_details: { name: state.name, email: state.email },
                            },
                        ])
                        .select()
                        .single();

                    if (dbError) console.error('Supabase error:', dbError);

                    if (insertedData && insertedData.order_id) {
                        setOfficialOrderId(insertedData.order_id);
                    }

                    setState(prev => ({ ...prev, step: 'success' }));
                    return true; // Stop polling
                } else {
                    // Not found yet
                    if (attempts >= maxAttempts) {
                        // Switch to manual upload instead of failed
                        setState(prev => ({ ...prev, step: 'manual_upload', error: '' }));
                        return true; // Stop polling
                    }
                    return false; // Continue polling
                }
            } catch (err: any) {
                console.error('Verification error:', err);
                // If it's a network error, we might want to keep retrying, but for now let's fail after max attempts
                if (attempts >= maxAttempts) {
                    setState(prev => ({ ...prev, step: 'failed', error: err.response?.data?.message || 'Server error during verification' }));
                    return true;
                }
                return false;
            }
        };

        // Start polling loop
        const poll = async () => {
            const stop = await checkPayment();
            if (!stop) {
                setTimeout(poll, pollInterval);
            }
        };

        poll();
    };

    const copyToClipboard = (text: string) => {
        navigator.clipboard.writeText(text);
        setCopied(true);
        setTimeout(() => setCopied(false), 2000);
    };

    // Generate UPI Intent Link
    const upiUrl = `upi://pay?pa=${UPI_ID}&pn=${encodeURIComponent(MERCHANT_NAME)}&am=${state.amount}&cu=INR`;

    const [uploading, setUploading] = useState(false);

    const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (!file) return;

        setUploading(true);
        try {
            const fileExt = file.name.split('.').pop();
            const fileName = `${sessionId}.${fileExt}`; // Use Session ID for filename
            const filePath = `${fileName}`;

            const { error: uploadError } = await supabase.storage
                .from('payment_proofs')
                .upload(filePath, file);

            if (uploadError) throw uploadError;

            const { data: { publicUrl } } = supabase.storage
                .from('payment_proofs')
                .getPublicUrl(filePath);

            // Update transaction with screenshot URL and status
            // Note: Since we haven't inserted the transaction yet (because auto-verify failed),
            // we insert it now. The trigger will NOT generate Order ID yet because status is pending_manual_verification.
            const { data: insertedData, error: updateError } = await supabase
                .from('transactions')
                .insert({
                    utr: state.utr || `MANUAL-${Date.now()}`, // Fallback if no UTR entered
                    amount: state.amount,
                    session_id: sessionId, // Store UUID in session_id
                    status: 'pending_manual_verification',
                    screenshot_url: publicUrl,
                    customer_details: { name: state.name, email: state.email }
                })
                .select()
                .single();

            if (updateError) throw updateError;

            // No official order ID yet for manual upload
            if (insertedData && insertedData.order_id) {
                setOfficialOrderId(insertedData.order_id);
            }

            setState(prev => ({ ...prev, step: 'success', screenshot_url: publicUrl })); // Update local state to show pending UI
        } catch (error: any) {
            console.error('Error uploading:', error);
            setState(prev => ({ ...prev, error: error.message || 'Error uploading screenshot' }));
        } finally {
            setUploading(false);
        }
    };

    // Listen for status updates (e.g. Admin approval)
    useEffect(() => {
        if (!sessionId) return;

        console.log('Setting up realtime subscription for session:', sessionId);

        const subscription = supabase
            .channel(`transaction_${sessionId}`)
            .on(
                'postgres_changes',
                {
                    event: 'UPDATE',
                    schema: 'public',
                    table: 'transactions',
                    filter: `session_id=eq.${sessionId}` // Listen specifically for this session UUID
                },
                (payload) => {
                    console.log('Transaction updated:', payload);
                    const newStatus = payload.new.status;
                    const newOrderId = payload.new.order_id;

                    if (newStatus === 'verified') {
                        if (newOrderId) {
                            setOfficialOrderId(newOrderId);
                        }
                        setState(prev => ({ ...prev, step: 'verified' }));
                    } else if (newStatus === 'rejected') {
                        setState(prev => ({ ...prev, step: 'failed', error: 'Payment verification rejected by admin.' }));
                    }
                }
            )
            .subscribe();

        return () => {
            supabase.removeChannel(subscription);
        };
    }, [sessionId]);

    const checkStatus = async () => {
        // If we have an official order ID, check by that.
        // If not, check by session_id or UTR.
        if (!officialOrderId && !sessionId && !state.utr) return;

        try {
            let query = supabase.from('transactions').select('status, order_id');

            if (officialOrderId) {
                query = query.eq('order_id', officialOrderId);
            } else if (sessionId) {
                query = query.eq('session_id', sessionId);
            } else {
                query = query.eq('utr', state.utr);
            }

            const { data, error } = await query.single();

            if (error) throw error;

            if (data?.status === 'verified') {
                if (data.order_id) setOfficialOrderId(data.order_id);
                setState(prev => ({ ...prev, step: 'verified' }));
            } else if (data?.status === 'rejected') {
                setState(prev => ({ ...prev, step: 'failed', error: 'Payment verification rejected by admin.' }));
            } else if (data?.status === 'pending_manual_verification') {
                alert('Your payment is still under review. We will notify you once approved.');
            } else {
                alert('Payment status: ' + (data?.status || 'pending'));
            }
        } catch (err) {
            console.error('Error checking status:', err);
        }
    };

    return (
        <div className="min-h-screen bg-[#F0F2F5] flex items-center justify-center p-4 font-sans selection:bg-slate-900 selection:text-white">

            <div className="bg-white w-full max-w-5xl rounded-2xl shadow-2xl overflow-hidden flex flex-col md:flex-row min-h-[600px] animate-slide-up">

                {/* Left Sidebar (Razorpay Style) */}
                <div className="md:w-[350px] bg-[#F9FAFB] border-r border-slate-100 p-8 flex flex-col justify-between relative">
                    <div>
                        <div className="flex items-center gap-3 mb-8">
                            <div className="w-10 h-10 bg-white rounded-lg shadow-sm border border-slate-200 flex items-center justify-center p-1">
                                <img src="/shark-logo-full.png" alt="Shark Funded" className="w-full h-full object-contain" />
                            </div>
                            <div>
                                <h3 className="font-bold text-slate-900 text-sm">Shark Funded</h3>
                                <div className="flex items-center gap-1 text-xs text-slate-500">
                                    <ShieldCheck size={10} className="text-emerald-500" />
                                    <span>Trusted Merchant</span>
                                </div>
                            </div>
                        </div>

                        <div className="space-y-6">
                            <div>
                                <p className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1">Amount to Pay</p>
                                <div className="flex items-baseline gap-1">
                                    <span className="text-3xl font-bold text-slate-900">₹{state.amount ? Number(state.amount).toLocaleString() : '0.00'}</span>
                                    <span className="text-slate-500 text-sm font-medium">INR</span>
                                </div>
                            </div>

                            {/* Official Order ID (Only on Success) */}
                            {officialOrderId && (
                                <div className="bg-emerald-50 p-3 rounded-lg border border-emerald-100 shadow-sm animate-fade-in">
                                    <p className="text-xs text-emerald-600 mb-1 font-bold">Order ID</p>
                                    <p className="font-mono text-sm font-bold text-emerald-800 break-all">{officialOrderId}</p>
                                </div>
                            )}

                            <div className="space-y-3 pt-6 border-t border-slate-200">
                                <div className="flex items-center gap-3">
                                    <div className="w-8 h-8 rounded-full bg-blue-50 flex items-center justify-center text-blue-600">
                                        <Lock size={14} />
                                    </div>
                                    <div>
                                        <p className="text-xs font-bold text-slate-700">Secure Payment</p>
                                        <p className="text-[10px] text-slate-500">256-bit SSL Encrypted</p>
                                    </div>
                                </div>
                                <div className="flex items-center gap-3">
                                    <div className="w-8 h-8 rounded-full bg-emerald-50 flex items-center justify-center text-emerald-600">
                                        <Check size={14} />
                                    </div>
                                    <div>
                                        <p className="text-xs font-bold text-slate-700">Instant Verification</p>
                                        <p className="text-[10px] text-slate-500">Automated confirmation</p>
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>

                    <div className="mt-8 md:mt-0 pt-6 border-t border-slate-200 md:border-0 md:pt-0">
                        <div className="flex items-center gap-2 opacity-60">
                            <span className="text-[10px] font-bold text-slate-400 uppercase tracking-wider">Powered by</span>
                            <span className="text-xs font-bold text-slate-600">Shark Payments</span>
                        </div>
                    </div>
                </div>

                {/* Right Content (Stripe Style) */}
                <div className="flex-1 p-8 md:p-12 flex flex-col justify-center relative">

                    {/* Back Button */}
                    {state.step === 'payment' && (
                        <button
                            onClick={() => setState(prev => ({ ...prev, step: 'details' }))}
                            className="absolute top-8 left-8 text-slate-400 hover:text-slate-700 transition-colors flex items-center gap-1 text-sm font-medium"
                        >
                            <ArrowLeft size={16} /> Back
                        </button>
                    )}

                    <div className="max-w-md mx-auto w-full">

                        {state.step === 'details' && (
                            <form onSubmit={handleDetailsSubmit} className="space-y-6 animate-fade-in">
                                <div className="mb-8">
                                    <h2 className="text-xl font-bold text-slate-900 mb-2">Contact Information</h2>
                                    <p className="text-slate-500 text-sm">Enter your details to proceed with the payment.</p>
                                </div>

                                <div className="space-y-5">
                                    <div>
                                        <label className="block text-sm font-medium text-slate-700 mb-1.5">Email Address</label>
                                        <input
                                            type="email"
                                            required
                                            className="w-full px-4 py-3 bg-white border border-slate-200 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 transition-all outline-none text-slate-900 placeholder:text-slate-400 shadow-sm"
                                            value={state.email}
                                            onChange={e => setState({ ...state, email: e.target.value })}
                                            placeholder="name@example.com"
                                        />
                                    </div>
                                    <div>
                                        <label className="block text-sm font-medium text-slate-700 mb-1.5">Full Name</label>
                                        <input
                                            type="text"
                                            required
                                            className="w-full px-4 py-3 bg-white border border-slate-200 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 transition-all outline-none text-slate-900 placeholder:text-slate-400 shadow-sm"
                                            value={state.name}
                                            onChange={e => setState({ ...state, name: e.target.value })}
                                            placeholder="John Doe"
                                        />
                                    </div>
                                    <div>
                                        <label className="block text-sm font-medium text-slate-700 mb-1.5">Amount</label>
                                        <div className="relative">
                                            <span className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-500 font-medium">₹</span>
                                            <input
                                                type="number"
                                                required
                                                min="1"
                                                className="w-full pl-8 pr-4 py-3 bg-white border border-slate-200 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 transition-all outline-none text-slate-900 font-medium placeholder:text-slate-400 shadow-sm"
                                                value={state.amount}
                                                onChange={e => setState({ ...state, amount: e.target.value })}
                                                placeholder="0.00"
                                            />
                                        </div>
                                    </div>
                                </div>

                                {state.error && (
                                    <div className="p-3 bg-rose-50 text-rose-600 text-sm rounded-lg flex items-center gap-2 border border-rose-100">
                                        <AlertCircle size={16} />
                                        <span className="font-medium">{state.error}</span>
                                    </div>
                                )}

                                <button
                                    type="submit"
                                    className="w-full bg-[#635BFF] text-white py-3.5 rounded-lg font-bold text-sm hover:bg-[#5851E3] hover:shadow-lg hover:shadow-blue-500/20 transition-all duration-200 flex items-center justify-center gap-2 mt-4"
                                >
                                    Pay ₹{state.amount ? Number(state.amount).toLocaleString() : '0.00'}
                                    <ArrowRight size={16} />
                                </button>
                            </form>
                        )}

                        {state.step === 'payment' && (
                            <div className="space-y-8 animate-fade-in">
                                <div className="text-center">
                                    <h2 className="text-xl font-bold text-slate-900 mb-2">Scan QR to Pay</h2>
                                    <div className="inline-flex items-center gap-1.5 px-3 py-1 bg-amber-50 text-amber-700 rounded-full text-xs font-bold border border-amber-100">
                                        <Clock size={12} className="animate-pulse" />
                                        Expires in {formatTime(timeLeft)}
                                    </div>
                                </div>

                                <div className="flex flex-col items-center">
                                    <div className="p-1 bg-white rounded-xl border border-slate-200 shadow-sm mb-4 cursor-pointer hover:shadow-md transition-all" onClick={() => copyToClipboard(upiUrl)}>
                                        <QRCodeSVG value={upiUrl} size={180} level="L" className="rounded-lg" />
                                        {copied && (
                                            <div className="absolute inset-0 flex items-center justify-center bg-white/90 rounded-xl backdrop-blur-sm">
                                                <span className="text-xs font-bold text-slate-900 flex items-center gap-1"><CheckCircle2 size={14} className="text-emerald-500" /> Copied</span>
                                            </div>
                                        )}
                                    </div>

                                    <div className="flex items-center gap-2 text-sm text-slate-600 bg-slate-50 px-3 py-1.5 rounded-md border border-slate-200 cursor-pointer hover:bg-slate-100" onClick={() => copyToClipboard(UPI_ID)}>
                                        <span className="font-mono font-medium">{UPI_ID}</span>
                                        <Copy size={14} className="text-slate-400" />
                                    </div>
                                </div>

                                <div className="pt-6 border-t border-slate-100">
                                    <label className="block text-sm font-medium text-slate-700 mb-2">Enter UTR / Reference Number</label>
                                    <div className="flex gap-2">
                                        <input
                                            type="text"
                                            className="flex-1 px-4 py-3 bg-white border border-slate-200 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 transition-all outline-none text-slate-900 font-mono font-medium placeholder:text-slate-400 shadow-sm"
                                            placeholder="12-digit UTR"
                                            value={state.utr}
                                            onChange={e => setState({ ...state, utr: e.target.value })}
                                        />
                                        <button
                                            onClick={handleVerify}
                                            className="px-6 bg-slate-900 text-white rounded-lg font-bold text-sm hover:bg-slate-800 transition-all shadow-md"
                                        >
                                            Verify
                                        </button>
                                    </div>
                                    <p className="text-xs text-slate-400 mt-2">
                                        Required to confirm your payment instantly.
                                    </p>
                                </div>
                            </div>
                        )}

                        {state.step === 'verifying' && (
                            <div className="text-center py-12 space-y-6 animate-fade-in">
                                <div className="w-16 h-16 border-4 border-slate-100 border-t-blue-600 rounded-full animate-spin mx-auto"></div>
                                <div>
                                    <h3 className="text-lg font-bold text-slate-900">Verifying Payment</h3>
                                    <p className="text-slate-500 text-sm mt-1">Confirming with the bank...</p>
                                </div>
                            </div>
                        )}

                        {(state.step === 'success' || state.step === 'verified') && (
                            <div className="text-center py-8 space-y-6 animate-scale-in">
                                <div className={`w-16 h-16 ${state.step === 'verified' ? 'bg-emerald-100 text-emerald-600' : 'bg-blue-100 text-blue-600'} rounded-full flex items-center justify-center mx-auto`}>
                                    {state.step === 'verified' ? <CheckCircle2 size={32} /> : <Clock size={32} />}
                                </div>
                                <div>
                                    <h2 className="text-2xl font-bold text-slate-900">
                                        {state.step === 'verified' ? 'Payment Verified' : state.screenshot_url ? 'Submitted for Review' : 'Payment Successful'}
                                    </h2>
                                    <p className="text-slate-500 text-sm mt-1">
                                        {state.step === 'verified' ? 'Your transaction has been confirmed.' : state.screenshot_url ? 'We will notify you once approved.' : 'Thank you for your payment.'}
                                    </p>
                                </div>

                                <div className="bg-slate-50 p-4 rounded-xl border border-slate-200 text-left space-y-2 text-sm">
                                    <div className="flex justify-between">
                                        <span className="text-slate-500">Amount Paid</span>
                                        <span className="font-bold text-slate-900">₹{Number(state.amount).toLocaleString()}</span>
                                    </div>
                                    <div className="flex justify-between">
                                        <span className="text-slate-500">Order ID</span>
                                        <span className="font-mono font-bold text-slate-900 break-all">{officialOrderId || 'Generating...'}</span>
                                    </div>
                                    <div className="flex justify-between">
                                        <span className="text-slate-500">Reference/UTR</span>
                                        <span className="font-mono font-bold text-slate-900">{state.utr}</span>
                                    </div>
                                </div>

                                <div className="space-y-3 pt-4">
                                    {state.screenshot_url && state.step !== 'verified' && (
                                        <button
                                            onClick={checkStatus}
                                            className="w-full bg-white text-slate-700 border border-slate-200 py-3 rounded-lg font-bold text-sm hover:bg-slate-50 transition-all"
                                        >
                                            Check Status
                                        </button>
                                    )}
                                    <button
                                        onClick={() => window.location.reload()}
                                        className="w-full bg-slate-900 text-white py-3 rounded-lg font-bold text-sm hover:bg-slate-800 transition-all"
                                    >
                                        Done
                                    </button>
                                </div>
                            </div>
                        )}

                        {state.step === 'failed' && (
                            <div className="text-center py-12 space-y-6 animate-scale-in">
                                <div className="w-16 h-16 bg-rose-100 text-rose-600 rounded-full flex items-center justify-center mx-auto">
                                    <AlertCircle size={32} />
                                </div>
                                <div>
                                    <h2 className="text-xl font-bold text-slate-900">Payment Failed</h2>
                                    <p className="text-rose-600 font-medium text-sm mt-2 bg-rose-50 px-3 py-1 rounded-full inline-block">{state.error}</p>
                                </div>
                                <button
                                    onClick={() => setState(prev => ({ ...prev, step: 'payment', error: '' }))}
                                    className="w-full bg-slate-900 text-white py-3 rounded-lg font-bold text-sm hover:bg-slate-800 transition-all"
                                >
                                    Try Again
                                </button>
                            </div>
                        )}

                        {state.step === 'manual_upload' && (
                            <div className="text-center py-8 space-y-6 animate-fade-in">
                                <div className="w-16 h-16 bg-amber-100 text-amber-600 rounded-full flex items-center justify-center mx-auto">
                                    <AlertCircle size={32} />
                                </div>
                                <div>
                                    <h2 className="text-xl font-bold text-slate-900">Manual Verification</h2>
                                    <p className="text-slate-500 text-sm mt-1">Please upload a screenshot of your payment.</p>
                                </div>

                                <div className="relative group max-w-xs mx-auto">
                                    <input
                                        type="file"
                                        accept="image/*"
                                        onChange={handleFileUpload}
                                        className="hidden"
                                        id="file-upload"
                                        disabled={uploading}
                                    />
                                    <label
                                        htmlFor="file-upload"
                                        className={`w-full flex flex-col items-center justify-center gap-2 px-4 py-6 border-2 border-dashed border-slate-300 rounded-xl cursor-pointer hover:border-slate-900 hover:bg-slate-50 transition-all ${uploading ? 'opacity-50 cursor-not-allowed' : ''}`}
                                    >
                                        {uploading ? (
                                            <Loader2 className="animate-spin text-slate-900" size={24} />
                                        ) : (
                                            <CreditCard size={24} className="text-slate-400" />
                                        )}
                                        <span className="font-bold text-sm text-slate-700">{uploading ? 'Uploading...' : 'Upload Proof'}</span>
                                    </label>
                                </div>
                                {state.error && <p className="text-rose-500 text-xs font-bold">{state.error}</p>}
                            </div>
                        )}

                        {state.step === 'expired' && (
                            <div className="text-center py-12 space-y-6 animate-scale-in">
                                <div className="w-16 h-16 bg-slate-100 text-slate-500 rounded-full flex items-center justify-center mx-auto">
                                    <Clock size={32} />
                                </div>
                                <div>
                                    <h2 className="text-xl font-bold text-slate-900">Session Expired</h2>
                                    <p className="text-slate-500 text-sm mt-1">Please start over.</p>
                                </div>
                                <button
                                    onClick={() => setState(prev => ({ ...prev, step: 'details', error: '' }))}
                                    className="w-full bg-slate-900 text-white py-3 rounded-lg font-bold text-sm hover:bg-slate-800 transition-all"
                                >
                                    Start Over
                                </button>
                            </div>
                        )}

                    </div>
                </div>
            </div>
        </div>
    );
};

export default PaymentPage;
